function renderDailyTip(){const start=new Date(new Date().getFullYear(),0,0),now=new Date();const day=Math.floor((now-start)/86400000);document.querySelector('#daily-tip-text').textContent=dailyTips[(day-1)%dailyTips.length][lang]}
const answers={
 jesus:{cecRef:'cec/422',keys:['qui est jesus','who is jesus','jesus christ','christ'],title:{fr:'Qui est Jésus ?',en:'Who is Jesus?'},body:{fr:'Pour la foi catholique, Jésus de Nazareth est le Christ, le Fils de Dieu fait homme : pleinement Dieu et pleinement homme. Les Évangiles le présentent annonçant le Royaume de Dieu, accueillant les personnes, enseignant et guérissant. Les chrétiens confessent sa mort et sa résurrection comme le cœur de la foi. Ces affirmations résument la foi de l’Église ; les récits bibliques qui les fondent ont chacun leur contexte et leur accent.',en:'In Catholic faith, Jesus of Nazareth is the Christ, the Son of God made man: fully God and fully human. The Gospels portray him proclaiming God’s Kingdom, welcoming people, teaching and healing. Christians confess his death and resurrection as the heart of their faith. These statements summarize the Church’s belief; the biblical accounts behind them each have their own context and emphasis.'},refs:[['Jean 1, 1-18','Jn/1'],['Marc 8, 27-35','Mc/8'],['Jean 20, 24-31','Jn/20'],['Catéchisme, §§ 422-455','https://www.vatican.va/archive/FRA0013/__P1F.HTM']]},
 love:{cecRef:'cec/1822',keys:['aimer son prochain','prochain','love your neighbor','love your neighbour','amour','love'],title:{fr:'Aimer son prochain',en:'Loving your neighbor'},body:{fr:'Jésus unit l’amour de Dieu et l’amour du prochain. Le prochain n’est pas seulement celui qui nous ressemble : la parabole du Samaritain invite à devenir proche de toute personne qui a besoin de nous. Pour les chrétiens, cet amour prend sa source en Dieu et se traduit en actes concrets.',en:'Jesus joins love of God with love of neighbor. Our neighbor is not only someone like us: the parable of the Samaritan calls us to become neighbor to anyone in need. For Christians, this love comes from God and takes shape in concrete actions.'},refs:[['Luc 10, 25-37','Lc/10'],['Matthieu 22, 34-40','Mt/22'],['Catéchisme, §§ 1822-1829','https://www.vatican.va/archive/FRA0013/__P66.HTM']]},
 saints:{cecRef:'cec/956',keys:['prier les saints','prier saint','why pray to saints','saints','intercession','marie','mary'],title:{fr:'La prière et les saints',en:'Prayer and the saints'},body:{fr:'La foi catholique distingue l’adoration, qui revient à Dieu seul, de la vénération des saints. Demander à un saint de prier pour nous est compris comme une demande d’intercession. Cette communion ne remplace jamais la médiation unique du Christ.',en:'Catholic faith distinguishes adoration, which belongs to God alone, from veneration of the saints. Asking a saint to pray for us is understood as a request for intercession. This communion never replaces the unique mediation of Christ.'},refs:[['Jean 2, 1-11','Jn/2'],['1 Timothée 2, 5','1Tm/2'],['Catéchisme, §§ 956 et 971','https://www.vatican.va/archive/FRA0013/__P2A.HTM']]},
 forgive:{cecRef:'cec/2840',keys:['pardon','pardonner','pardonne','forgiveness','forgive'],title:{fr:'Le pardon dans la Bible',en:'Forgiveness in the Bible'},body:{fr:'Jésus enseigne le pardon et le met au cœur de la prière chrétienne. Pardonner ne signifie pas nier le mal subi, renoncer à la justice ou rester dans une situation dangereuse. C’est un chemin qui peut demander du temps et de l’accompagnement.',en:'Jesus teaches forgiveness and places it at the heart of Christian prayer. Forgiving does not mean denying harm, giving up justice, or staying in an unsafe situation. It is a path that can take time and support.'},refs:[['Matthieu 18, 21-35','Mt/18'],['Luc 23, 34','Lc/23'],['Catéchisme, §§ 2840-2845','https://www.vatican.va/archive/FRA0013/__P9R.HTM']]},
 trinity:{cecRef:'cec/232',keys:['trinité','trinity','père fils esprit','father son holy spirit'],title:{fr:'La Trinité',en:'The Trinity'},body:{fr:'La foi chrétienne confesse un seul Dieu en trois personnes : le Père, le Fils et l’Esprit Saint. Ce n’est pas trois dieux. « Trinité » est un terme théologique qui résume la manière dont l’Église comprend le témoignage biblique sur Dieu.',en:'Christian faith confesses one God in three Persons: Father, Son, and Holy Spirit. This is not three gods. “Trinity” is a theological term that summarizes how the Church understands the Bible’s witness about God.'},refs:[['Matthieu 28, 19','Mt/28'],['2 Corinthiens 13, 13','2Co/13'],['Catéchisme, §§ 232-267','https://www.vatican.va/archive/FRA0013/__P19.HTM']]},
 suffering:{cecRef:'cec/309',keys:['souffrance','pourquoi dieu permet','why does god allow','suffering','evil','mal'],title:{fr:'Dieu face à la souffrance',en:'God and suffering'},body:{fr:'La Bible ne donne pas une explication simple à toute souffrance. Le livre de Job refuse les réponses toutes faites et les psaumes donnent place à la plainte. La foi chrétienne affirme que Dieu rejoint l’humanité dans le Christ crucifié et ressuscité, sans prétendre que cela rend la douleur facile.',en:'The Bible does not offer a simple explanation for every kind of suffering. The book of Job rejects easy answers, and the Psalms make room for lament. Christian faith says that God meets humanity in the crucified and risen Christ, without pretending that this makes pain easy.'},refs:[['Job 3 ; 38–42','Jb/3'],['Psaume 22','Ps/22'],['Jean 11, 32-36','Jn/11'],['Catéchisme, §§ 309-314','https://www.vatican.va/archive/FRA0013/__P1B.HTM']]},
 eucharist:{cecRef:'cec/1322',keys:['messe','eucharistie','communion','eucharist','mass'],title:{fr:'L’Eucharistie',en:'The Eucharist'},body:{fr:'Pour les catholiques, l’Eucharistie est le mémorial de la Pâque du Christ et le sacrement de sa présence. L’Église relie cette foi aux paroles de Jésus à la dernière Cène et au discours sur le pain de vie. Les traditions chrétiennes interprètent certains aspects différemment.',en:'For Catholics, the Eucharist is the memorial of Christ’s Passover and the sacrament of his presence. The Church connects this belief with Jesus’ words at the Last Supper and his teaching about the bread of life. Christian traditions interpret some aspects differently.'},refs:[['Luc 22, 14-20','Lc/22'],['Jean 6, 51-58','Jn/6'],['Catéchisme, §§ 1322-1419','https://www.vatican.va/archive/FRA0013/__P3W.HTM']]},
 bible:{cecRef:'cec/101',keys:['lire la bible','commencer','where to start','read the bible','bible'],title:{fr:'Lire la Bible',en:'Reading the Bible'},body:{fr:'Vous pouvez commencer par un évangile — Marc est bref, Luc met en valeur la miséricorde — puis lire les Actes des Apôtres et quelques psaumes. Les catholiques lisent l’Écriture dans la Tradition vivante de l’Église, en tenant compte du genre littéraire et du contexte historique.',en:'You might begin with a Gospel—Mark is brief, while Luke emphasizes mercy—then read Acts and some Psalms. Catholics read Scripture within the living Tradition of the Church, taking literary genre and historical context into account.'},refs:[['Dei Verbum, § 12','https://www.vatican.va/archive/hist_councils/ii_vatican_council/documents/vat-ii_const_19651118_dei-verbum_fr.html'],['Catéchisme, §§ 101-141','https://www.vatican.va/archive/FRA0013/__P29.HTM']]},
 confession:{cecRef:'cec/1422',keys:['confession','réconciliation','se confesser','reconciliation'],title:{fr:'Le sacrement de réconciliation',en:'The Sacrament of Reconciliation'},body:{fr:'Dans la tradition catholique, le sacrement de réconciliation est un signe du pardon de Dieu et de la réconciliation avec l’Église. Jésus confie à ses disciples un ministère de réconciliation. Pour une situation personnelle ou douloureuse, un prêtre peut accompagner avec discernement.',en:'In Catholic tradition, the Sacrament of Reconciliation is a sign of God’s forgiveness and reconciliation with the Church. Jesus entrusts his disciples with a ministry of reconciliation. For a personal or painful situation, a priest can offer pastoral guidance.'},refs:[['Jean 20, 21-23','Jn/20'],['2 Corinthiens 5, 18-20','2Co/5'],['Catéchisme, §§ 1422-1498','https://www.vatican.va/archive/FRA0013/__P4D.HTM']]}
};
let lang=localStorage.getItem('pc-lang')||'fr';let dark=localStorage.getItem('pc-dark')==='true';const form=document.querySelector('#ask-form'),input=document.querySelector('#question'),conversation=document.querySelector('#conversation');
function normalize(s){return s.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function setLang(next){lang=next;localStorage.setItem('pc-lang',lang);document.documentElement.lang=lang;document.querySelector('#language').textContent=lang==='fr'?'EN':'FR';document.querySelectorAll('[data-i18n]').forEach(el=>{const v=messages[lang][el.dataset.i18n];if(v)el.textContent=v});document.querySelectorAll('[data-html-i18n]').forEach(el=>{const v=messages[lang][el.dataset.htmlI18n];if(v)el.innerHTML=v});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=messages[lang][el.dataset.i18nPlaceholder]);document.querySelectorAll('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',messages[lang][el.dataset.i18nAria]));document.querySelectorAll('.suggestions button').forEach(el=>{el.innerHTML=messages[lang][el.dataset.i18n]+' <span>↗</span>'});document.querySelector('#theme').title=dark?messages[lang].light:messages[lang].dark;document.querySelector('#theme').setAttribute('aria-label',dark?messages[lang].light:messages[lang].dark);document.querySelector('#daily-date').textContent=`${messages[lang].todayDate} ${new Intl.DateTimeFormat(lang==='fr'?'fr-FR':'en-US',{dateStyle:'long'}).format(new Date())}`;renderDailyTip()}
function setDark(value){dark=value;document.body.classList.toggle('dark',dark);localStorage.setItem('pc-dark',dark);document.querySelector('#theme').textContent=dark?'☀':'☾';document.querySelector('#theme').title=dark?messages[lang].light:messages[lang].dark;document.querySelector('#theme').setAttribute('aria-label',dark?messages[lang].light:messages[lang].dark)}
function safe(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function aelfLink(ref){return `https://www.aelf.org/bible/${ref}`}
async function answer(q){const n=normalize(q),found=Object.values(answers).map(x=>({...x,score:x.keys.reduce((a,k)=>a+(n.includes(normalize(k))?1:0),0)})).sort((a,b)=>b.score-a.score)[0];if(found?.score){let title=found.title[lang],body=found.body[lang],context='';try{const url=`https://api.theofons.net/v1/locus?ref=${encodeURIComponent(found.cecRef)}&text=1&lang=${lang}`;const r=await fetch(url,{headers:{Accept:'application/json'}});if(r.ok){const d=await r.json(),txt=d.text||d.paragraph?.text||d.content;if(typeof txt==='string'&&txt.trim()){const excerpt=txt.trim().split(/\s+/).slice(0,22).join(' ');context=`<div class="api-reference"><b>${messages[lang].apiCatechism}</b><p>“${safe(excerpt)}${txt.trim().split(/\s+/).length>22?'…':''}”</p><a href="${url}" target="_blank" rel="noreferrer">${safe(d.label||found.cecRef)} · TheoFons API ↗</a></div>`}}}catch(_){context=''}return `<h3>${title}</h3><p>${body}</p>${context}<p><b>${lang==='fr'?'Pour approfondir :':'Read further:'}</b></p><ul>${found.refs.map(([label,url])=>`<li><a href="${url.startsWith('http')?url:aelfLink(url)}" target="_blank" rel="noreferrer">${label} ↗</a></li>`).join('')}</ul><p><i>${lang==='fr'?'Ce résumé présente des repères catholiques généraux. Le contexte des passages apporte des nuances.':'This summary presents general Catholic teaching. The context of each passage adds nuance.'}</i></p>`}return lang==='fr'?`<h3>Pour avancer dans votre question</h3><p>Je ne trouve pas encore de réponse assez précise dans mes repères. Je préfère ne pas improviser une citation ou une référence. Précisez le passage biblique ou reformulez votre question ; je vous aiderai à distinguer le texte, son contexte et la lecture catholique.</p><p>Consultez la <a href="https://www.aelf.org/bible" target="_blank" rel="noreferrer">Bible AELF ↗</a> ou le <a href="https://www.vatican.va/archive/FRA0013/_INDEX.HTM" target="_blank" rel="noreferrer">Catéchisme ↗</a>.</p>`:`<h3>Let’s explore your question</h3><p>I don’t yet have a precise enough reference for this question, so I won’t invent a quotation or citation. If you share a Bible passage or rephrase the question, I can help distinguish the text, its context, and the Catholic interpretation.</p><p>See the <a href="https://www.aelf.org/bible" target="_blank" rel="noreferrer">AELF Bible ↗</a> or the <a href="https://www.vatican.va/archive/FRA0013/_INDEX.HTM" target="_blank" rel="noreferrer">Catechism ↗</a>.</p>`}
function addMessage(text,cls,html=false){const el=document.createElement('div');el.className=`message ${cls}`;const bubble=document.createElement('div');bubble.className='bubble';if(html)bubble.innerHTML=text;else bubble.textContent=text;el.append(bubble);if(cls==='assistant'&&!bubble.classList.contains('typing')){lastAssistantReply=bubble.innerText;setReplyButtons(true);const follow=document.createElement('div');follow.className='message-suggestions';follow.innerHTML=lang==='fr'?'<button data-q="Où lire un passage sur l’espérance ?" data-q-en="Where can I read about hope?">Explorer un autre passage</button><button data-q="Comment prier avec la Bible ?" data-q-en="How can I pray with the Bible?">Prier avec la Bible</button>':'<button data-q="Où lire un passage sur l’espérance ?" data-q-en="Where can I read about hope?">Explore another passage</button><button data-q="Comment prier avec la Bible ?" data-q-en="How can I pray with the Bible?">Pray with the Bible</button>';el.append(follow)}conversation.append(el);conversation.scrollTop=conversation.scrollHeight}
let lastAssistantReply='';
function setReplyButtons(enabled){document.querySelectorAll('.reply-action').forEach(button=>button.disabled=!enabled)}
async function copyReply(){if(!lastAssistantReply)return false;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(lastAssistantReply);return true}const field=document.createElement('textarea');field.value=lastAssistantReply;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();const copied=document.execCommand('copy');field.remove();return copied}catch(_){return false}}
function renderReplyActions(){const fr=lang==='fr';document.querySelector('#reply-actions-title').textContent=fr?'Actions':'Actions';document.querySelector('.reply-actions').setAttribute('aria-label',fr?'Actions sur la dernière réponse':'Actions for the latest answer');document.querySelector('#copy-answer-label').textContent=fr?'Copier':'Copy';document.querySelector('#save-answer-label').textContent=fr?'Favori':'Save';document.querySelector('#share-answer-label').textContent=fr?'Partager':'Share';document.querySelector('#copy-answer').setAttribute('aria-label',fr?'Copier la dernière réponse':'Copy the latest answer');document.querySelector('#save-answer').setAttribute('aria-label',fr?'Enregistrer la dernière réponse dans les favoris':'Save the latest answer to favourites');document.querySelector('#share-answer').setAttribute('aria-label',fr?'Partager la dernière réponse':'Share the latest answer')}
function initReplyActions(){const copy=document.querySelector('#copy-answer'),save=document.querySelector('#save-answer'),share=document.querySelector('#share-answer');const flash=(el,label)=>{const target=el.querySelector('span:last-child'),before=target.textContent;target.textContent=label;setTimeout(()=>target.textContent=before,1700)};copy.addEventListener('click',async()=>{const ok=await copyReply();flash(copy,ok?(lang==='fr'?'Copié ✓':'Copied ✓'):(lang==='fr'?'Indisponible':'Unavailable'))});save.addEventListener('click',()=>{if(!lastAssistantReply)return;saveFavorite(lastAssistantReply);flash(save,lang==='fr'?'Enregistré ✓':'Saved ✓')});share.addEventListener('click',async()=>{if(!lastAssistantReply)return;if(navigator.share){try{await navigator.share({title:'IA Bible',text:lastAssistantReply});flash(share,lang==='fr'?'Partagé ✓':'Shared ✓')}catch(_){}}else{const ok=await copyReply();flash(share,ok?(lang==='fr'?'Copié pour partager ✓':'Copied to share ✓'):(lang==='fr'?'Indisponible':'Unavailable'))}});conversation.addEventListener('click',e=>{const question=e.target.closest('[data-q]');if(question)submit(lang==='fr'?question.dataset.q:question.dataset.qEn)});renderReplyActions();document.querySelector('#language').addEventListener('click',renderReplyActions)}
let agentHistory=[];let backendAvailable=false;
function updateAgentStatus(available){backendAvailable=available;const status=document.querySelector('#agent-status'),dot=document.querySelector('#agent-dot');status.textContent=available?messages[lang].readyAI:messages[lang].readyFallback;dot.classList.toggle('offline',!available)}
async function checkAgent(){try{const r=await fetch('/api/status');if(!r.ok)throw new Error('offline');const data=await r.json();updateAgentStatus(Boolean(data.available))}catch(_){updateAgentStatus(false)}}
function renderAgentText(text){let html=safe(text).replace(/\[([^\]]+)\]\((https:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noreferrer">$1</a>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>');return html}
async function submit(q){const clean=q.trim();if(!clean)return;addMessage(clean,'user-message');agentHistory.push({role:'user',content:clean});input.value='';const t=document.createElement('div');t.className='message assistant';t.innerHTML=`<div class="bubble typing">${messages[lang].typing}</div>`;conversation.append(t);conversation.scrollTop=conversation.scrollHeight;let responseHtml='',plainAnswer='';try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:agentHistory.slice(-12),lang})});if(!r.ok)throw new Error('API offline');const data=await r.json();if(!data.answer)throw new Error('Empty response');plainAnswer=data.answer;responseHtml=renderAgentText(data.answer);agentHistory.push({role:'assistant',content:data.answer});updateAgentStatus(true)}catch(_){try{responseHtml=await answer(clean);plainAnswer=document.createElement('div');plainAnswer.innerHTML=responseHtml;plainAnswer=plainAnswer.innerText;agentHistory.push({role:'assistant',content:'[Réponse guidée locale]'});updateAgentStatus(false)}catch(e){responseHtml=`<p>${messages[lang].unavailable}</p>`;plainAnswer=messages[lang].unavailable}}t.remove();addMessage(responseHtml,'assistant',true);const history=readStore('pc-history');history.push({q:clean,a:plainAnswer});localStorage.setItem('pc-history',JSON.stringify(history.slice(-30)));renderHistory()}
form.addEventListener('submit',e=>{e.preventDefault();submit(input.value)});document.querySelectorAll('.suggestions button').forEach(b=>b.addEventListener('click',()=>submit(lang==='fr'?b.dataset.q:b.dataset.qEn)));document.querySelector('#reset').addEventListener('click',()=>location.reload());document.querySelector('#language').addEventListener('click',()=>{setLang(lang==='fr'?'en':'fr');document.querySelector('#agent-status').textContent=backendAvailable?messages[lang].readyAI:messages[lang].readyFallback;renderResources();renderInteractive();loadApiVerse()});document.querySelector('#theme').addEventListener('click',()=>setDark(!dark));input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();form.requestSubmit()}});
document.querySelector('#year').textContent=new Date().getFullYear();setDark(dark);setLang(lang);checkAgent();
// Holy Bible API (keyless, third-party): prefer a French translation when available; keep AELF verse as a reliable fallback.
async function loadApiVerse(){const link=document.querySelector('#daily-ref');try{const r=await fetch('https://holy-bible-api.com/bibles',{headers:{Accept:'application/json'}});if(!r.ok)return;const data=await r.json();const list=Array.isArray(data)?data:(data.bibles||data.items||data.results||[]);const bible=list.find(b=>{const s=JSON.stringify(b).toLowerCase();return lang==='fr'?(s.includes('french')||s.includes('français')):s.includes('english')});const id=bible&&(bible.id||bible.bible_id);if(!id)return;const endpoint=`https://holy-bible-api.com/bibles/${encodeURIComponent(id)}/verse-of-the-day`;const v=await fetch(endpoint,{headers:{Accept:'application/json'}});if(!v.ok)return;const item=await v.json();const verse=item.verse||item;const text=item.text||verse.text||item.verse_text;if(!text)return;document.querySelector('#daily-verse').textContent='“'+text.trim()+'”';const book=verse.book_name||verse.book?.name||item.book_name||'';const chapter=verse.chapter_num||verse.chapter||item.chapter_num||'';const number=verse.verse_num||verse.verse||item.verse_num||'';const ref=item.reference||verse.reference||(book&&chapter?`${book} ${chapter}${number?':'+number:''}`:'');link.textContent=(ref||messages[lang].today)+' · Holy Bible ↗';link.href=endpoint;link.title=lang==='fr'?'Ouvrir le verset du jour fourni par Holy Bible API':'Open today’s verse from the Holy Bible API'}catch(_){/* Keep the AELF verse and link as the fallback. */}}
loadApiVerse();


async function loadAelfReadings(){const box=document.querySelector('#daily-readings');try{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const values=Object.fromEntries(parts.map(p=>[p.type,p.value]));const date=`${values.year}-${values.month}-${values.day}`;const url=`https://api.aelf.org/v1/messes/${date}/france`;const r=await fetch(url,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('AELF');const data=await r.json();const items=[];function walk(node,path=[]){if(!node||typeof node!=='object')return;if(Array.isArray(node)){node.forEach(x=>walk(x,path));return}const key=path.at(-1)||'';if(/evangile|psaume|lecture|cantique|acclamation/i.test(key)){const ref=node.reference||node.ref||node.titre||node.title||node.livre;const text=node.texte||node.text||node.contenu;if(typeof ref==='string')items.push({label:key,ref});else if(typeof text==='string')items.push({label:key,ref:text.slice(0,160)})}for(const [k,v] of Object.entries(node))walk(v,[...path,k])}walk(data);const unique=[...new Map(items.map(x=>[x.ref,x])).values()].slice(0,6);if(!unique.length){box.innerHTML=`<a href="${url}" target="_blank" rel="noreferrer">${lang==='fr'?'Voir les lectures du jour sur l’API AELF ↗':'View today’s readings in the AELF API ↗'}</a>`;return}box.innerHTML=unique.map(x=>`<div><b>${safe(x.label.replaceAll('_',' '))}</b> ${safe(x.ref)}</div>`).join('')}catch(_){box.innerHTML=`<a href="https://api.aelf.org/" target="_blank" rel="noreferrer">${messages[lang].unavailable} · AELF ↗</a>`}}
loadAelfReadings();





