function easterDate(year){const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=(h+l-7*m+114)%31+1;return new Date(year,month-1,day)}
function shifted(date,days){const result=new Date(date);result.setDate(result.getDate()+days);return result}
function upcomingFeasts(){const today=new Date();today.setHours(0,0,0,0);const events=[];for(let year=today.getFullYear();year<=today.getFullYear()+2;year++){const fixed=[[[11,1],{fr:'Toussaint',en:'All Saints’ Day'},{fr:'L’Église célèbre tous les saints, connus et inconnus, et rappelle l’appel de chacun à la sainteté.',en:'The Church celebrates all the saints, known and unknown, and recalls the call to holiness.'}],[[11,2],{fr:'Commémoration des fidèles défunts',en:'All Souls’ Day'},{fr:'Les fidèles prient pour les personnes défuntes et font mémoire de l’espérance chrétienne en la vie éternelle.',en:'The faithful pray for the dead and remember the Christian hope of eternal life.'}],[[12,8],{fr:'Immaculée Conception',en:'Immaculate Conception'},{fr:'Cette solennité célèbre la foi catholique selon laquelle Marie a été préservée du péché originel dès sa conception.',en:'This solemnity celebrates the Catholic belief that Mary was preserved from original sin from the first moment of her conception.'}],[[12,25],{fr:'Noël',en:'Christmas'},{fr:'Les chrétiens célèbrent la naissance de Jésus, le Fils de Dieu fait homme.',en:'Christians celebrate the birth of Jesus, the Son of God made man.'}],[[1,1],{fr:'Sainte Marie, Mère de Dieu',en:'Mary, Mother of God'},{fr:'Cette fête honore Marie comme Mère de Dieu parce que Jésus, son fils, est pleinement Dieu et pleinement homme.',en:'This feast honours Mary as Mother of God because Jesus, her son, is fully God and fully human.'}],[[2,2],{fr:'Présentation du Seigneur',en:'Presentation of the Lord'},{fr:'Elle rappelle la présentation de Jésus au Temple de Jérusalem, quarante jours après sa naissance.',en:'It recalls the presentation of Jesus in the Jerusalem Temple, forty days after his birth.'}]];for(const [[month,day],name,description]of fixed)events.push({date:new Date(year,month-1,day),name,description});const jan2=new Date(year,0,2),epiphany=new Date(year,0,2+((7-jan2.getDay())%7));events.push({date:epiphany,name:{fr:'Épiphanie',en:'Epiphany'},description:{fr:'Elle célèbre la manifestation de Jésus comme Sauveur de tous les peuples, représentés dans l’Évangile par les mages.',en:'It celebrates Jesus revealed as the Saviour of all peoples, represented in the Gospel by the Magi.'}});const christmas=new Date(year,11,25),advent=shifted(christmas,-((christmas.getDay()+6)%7)-21);events.push({date:advent,name:{fr:'1er dimanche de l’Avent',en:'First Sunday of Advent'},description:{fr:'L’Avent ouvre une nouvelle année liturgique et prépare à célébrer la naissance du Christ, dans l’attente de sa venue.',en:'Advent begins a new liturgical year and prepares Christians to celebrate Christ’s birth while awaiting his coming.'}});const easter=easterDate(year);for(const [offset,name,description]of [[-46,{fr:'Mercredi des Cendres',en:'Ash Wednesday'},{fr:'Il marque le début du Carême, temps de prière, de jeûne et de partage en préparation à Pâques.',en:'It marks the beginning of Lent, a season of prayer, fasting and sharing in preparation for Easter.'}],[-7,{fr:'Dimanche des Rameaux',en:'Palm Sunday'},{fr:'Il commémore l’entrée de Jésus à Jérusalem et ouvre la Semaine sainte.',en:'It commemorates Jesus’ entry into Jerusalem and begins Holy Week.'}],[-2,{fr:'Vendredi saint',en:'Good Friday'},{fr:'Les chrétiens font mémoire de la Passion et de la mort de Jésus sur la croix.',en:'Christians remember the Passion and death of Jesus on the cross.'}],[0,{fr:'Pâques · Résurrection du Christ',en:'Easter · Resurrection of the Lord'},{fr:'La fête centrale de la foi chrétienne : elle célèbre la résurrection de Jésus, le troisième jour après sa mort.',en:'The central feast of Christian faith celebrates Jesus’ resurrection on the third day after his death.'}],[39,{fr:'Ascension',en:'Ascension'},{fr:'Quarante jours après Pâques, l’Église célèbre l’élévation du Christ auprès du Père.',en:'Forty days after Easter, the Church celebrates Christ’s ascension to the Father.'}],[49,{fr:'Pentecôte',en:'Pentecost'},{fr:'Elle célèbre le don de l’Esprit Saint aux apôtres et la naissance missionnaire de l’Église.',en:'It celebrates the gift of the Holy Spirit to the apostles and the Church’s mission.'}]])events.push({date:shifted(easter,offset),name,description})}return events.filter(e=>e.date>=today).sort((a,b)=>a.date-b.date).slice(0,6)}
function renderCalendar(){const fmt=new Intl.DateTimeFormat(lang==='fr'?'fr-FR':'en-US',{day:'numeric',month:'short',year:'numeric'});document.querySelector('#calendar-list').innerHTML=upcomingFeasts().map(item=>`<details class="calendar-event"><summary><time datetime="${item.date.toISOString().slice(0,10)}">${fmt.format(item.date)}</time><b>${item.name[lang]}</b><span class="calendar-chevron" aria-hidden="true">⌄</span></summary><p>${item.description[lang]}</p></details>`).join('')}
