const dayFacts=[{fr:'Saint François d’Assise est associé à une vie de pauvreté évangélique et à l’attention portée à la création.',en:'Saint Francis of Assisi is associated with evangelical poverty and care for creation.'},{fr:'Sainte Thérèse de Lisieux a développé une spiritualité de confiance et de petites actions vécues avec amour.',en:'Saint Thérèse of Lisieux developed a spirituality of trust and small acts done with love.'},{fr:'Saint Augustin, évêque d’Hippone, est l’un des grands auteurs chrétiens de l’Antiquité.',en:'Saint Augustine, bishop of Hippo, is one of the major Christian writers of late antiquity.'},{fr:'Sainte Joséphine Bakhita, née au Soudan, témoigna de la foi après avoir connu l’esclavage.',en:'Saint Josephine Bakhita, born in Sudan, bore witness to faith after experiencing enslavement.'},{fr:'Saint Martin de Tours est connu dans la tradition pour son geste de partage avec un pauvre.',en:'Saint Martin of Tours is remembered in tradition for sharing his cloak with a poor man.'}];
const quizzes=[{q:{fr:'Dans quelle ville Jésus est-il né selon les Évangiles ?',en:'In which town was Jesus born according to the Gospels?'},options:{fr:['Nazareth','Bethléem','Jérusalem'],en:['Nazareth','Bethlehem','Jerusalem']},correct:1,why:{fr:'Matthieu 2 et Luc 2 situent la naissance de Jésus à Bethléem.',en:'Matthew 2 and Luke 2 place Jesus’ birth in Bethlehem.'}},{q:{fr:'Qui reçoit les Dix Commandements dans le livre de l’Exode ?',en:'Who receives the Ten Commandments in Exodus?'},options:{fr:['Moïse','Élie','David'],en:['Moses','Elijah','David']},correct:0,why:{fr:'Moïse reçoit les commandements au Sinaï (Exode 20).',en:'Moses receives the commandments at Sinai (Exodus 20).'}},{q:{fr:'Quel évangile commence par « Au commencement était le Verbe » ?',en:'Which Gospel begins “In the beginning was the Word”?'},options:{fr:['Marc','Jean','Luc'],en:['Mark','John','Luke']},correct:1,why:{fr:'C’est le prologue de l’Évangile selon Jean (Jean 1, 1).',en:'This is the prologue of John’s Gospel (John 1:1).'}},{q:{fr:'Quel est le premier livre de la Bible ?',en:'What is the first book of the Bible?'},options:{fr:['Genèse','Psaumes','Exode'],en:['Genesis','Psalms','Exodus']},correct:0,why:{fr:'La Genèse ouvre la Bible et raconte notamment les origines.',en:'Genesis opens the Bible and includes accounts of beginnings.'}},{q:{fr:'Qui baptise Jésus dans le Jourdain ?',en:'Who baptizes Jesus in the Jordan?'},options:{fr:['Pierre','Jean le Baptiste','André'],en:['Peter','John the Baptist','Andrew']},correct:1,why:{fr:'Jean baptise Jésus dans le Jourdain (Matthieu 3, 13-17).',en:'John baptizes Jesus in the Jordan (Matthew 3:13–17).'}},{q:{fr:'Quel disciple a renié Jésus trois fois ?',en:'Which disciple denied Jesus three times?'},options:{fr:['Jean','Pierre','Thomas'],en:['John','Peter','Thomas']},correct:1,why:{fr:'Pierre renie Jésus trois fois avant le chant du coq (Luc 22, 54-62).',en:'Peter denies Jesus three times before the rooster crows (Luke 22:54–62).'}},{q:{fr:'Quel prophète a affronté les prophètes de Baal sur le mont Carmel ?',en:'Which prophet confronted the prophets of Baal on Mount Carmel?'},options:{fr:['Élie','Isaïe','Jérémie'],en:['Elijah','Isaiah','Jeremiah']},correct:0,why:{fr:'Le récit se trouve en 1 Rois 18, 20-40.',en:'The account is in 1 Kings 18:20–40.'}},{q:{fr:'Combien d’évangiles trouve-t-on dans le Nouveau Testament ?',en:'How many Gospels are in the New Testament?'},options:{fr:['Deux','Quatre','Sept'],en:['Two','Four','Seven']},correct:1,why:{fr:'Les quatre évangiles sont selon Matthieu, Marc, Luc et Jean.',en:'The four Gospels are Matthew, Mark, Luke, and John.'}},{q:{fr:'Quel homme est avalé par un grand poisson ?',en:'Which man is swallowed by a great fish?'},options:{fr:['Jonas','Job','Josué'],en:['Jonah','Job','Joshua']},correct:0,why:{fr:'Le livre de Jonas raconte cet épisode (Jonas 2, 1).',en:'The Book of Jonah tells this episode (Jonah 1:17).'}},{q:{fr:'Quel est le nom de la mère de Jésus ?',en:'What is the name of Jesus’ mother?'},options:{fr:['Marthe','Marie','Élisabeth'],en:['Martha','Mary','Elizabeth']},correct:1,why:{fr:'Les évangiles nomment Marie comme la mère de Jésus (Luc 1, 30-31).',en:'The Gospels name Mary as Jesus’ mother (Luke 1:30–31).'}},{q:{fr:'Quel apôtre est connu comme le « disciple que Jésus aimait » dans l’Évangile selon Jean ?',en:'Which apostle is known as “the disciple whom Jesus loved” in John’s Gospel?'},options:{fr:['Jean','Matthieu','Philippe'],en:['John','Matthew','Philip']},correct:0,why:{fr:'Cette expression apparaît notamment en Jean 13, 23. L’identification traditionnelle est Jean, même si le texte ne donne pas son nom.',en:'This expression appears, for example, in John 13:23. Tradition identifies him as John, though the text does not name him.'}},{q:{fr:'Quel livre raconte la sortie d’Égypte du peuple d’Israël ?',en:'Which book tells of the Israelites’ departure from Egypt?'},options:{fr:['Exode','Lévitique','Ruth'],en:['Exodus','Leviticus','Ruth']},correct:0,why:{fr:'L’Exode raconte la libération d’Égypte et le chemin vers le Sinaï.',en:'Exodus recounts the liberation from Egypt and the journey to Sinai.'}},{q:{fr:'Quel apôtre a remplacé Judas parmi les Douze ?',en:'Which apostle replaced Judas among the Twelve?'},options:{fr:['Barnabé','Matthias','Paul'],en:['Barnabas','Matthias','Paul']},correct:1,why:{fr:'Matthias est choisi après la résurrection (Actes 1, -verset 26).',en:'Matthias is chosen after the resurrection (Acts 1:26).'}},{q:{fr:'Quel est le dernier livre du Nouveau Testament ?',en:'What is the last book of the New Testament?'},options:{fr:['Les Actes des Apôtres','L’Apocalypse','La Lettre aux Hébreux'],en:['Acts of the Apostles','Revelation','Hebrews']},correct:1,why:{fr:'L’Apocalypse clôt le Nouveau Testament.',en:'Revelation is the final book of the New Testament.'}},{q:{fr:'Qui a reçu la visite de l’ange Gabriel annonçant la naissance de Jésus ?',en:'Who was visited by the angel Gabriel announcing Jesus’ birth?'},options:{fr:['Marie','Marthe','Anne'],en:['Mary','Martha','Anna']},correct:0,why:{fr:'L’Annonciation est racontée en Luc 1, 26-38.',en:'The Annunciation is told in Luke 1:26–38.'}},{q:{fr:'Quel roi est associé aux psaumes et à l’histoire de David et Goliath ?',en:'Which king is associated with the Psalms and the story of David and Goliath?'},options:{fr:['Salomon','David','Saül'],en:['Solomon','David','Saul']},correct:1,why:{fr:'David vainc Goliath (1 Samuel 17) et la tradition biblique lui attribue plusieurs psaumes.',en:'David defeats Goliath (1 Samuel 17), and biblical tradition attributes several psalms to him.'}},{q:{fr:'Quel miracle Jésus accomplit-il lors des noces de Cana ?',en:'What miracle does Jesus perform at the wedding at Cana?'},options:{fr:['Il marche sur l’eau','Il change l’eau en vin','Il multiplie les pains'],en:['He walks on water','He turns water into wine','He multiplies loaves']},correct:1,why:{fr:'Le signe de Cana est raconté en Jean 2, 1-11.',en:'The sign at Cana is told in John 2:1–11.'}},{q:{fr:'Sur quelle montagne Jésus prononce-t-il le discours appelé le Sermon sur la montagne ?',en:'On which mountain does Jesus give the teaching known as the Sermon on the Mount?'},options:{fr:['Le mont des Oliviers','Une montagne en Galilée','Le mont Sinaï'],en:['The Mount of Olives','A mountain in Galilee','Mount Sinai']},correct:1,why:{fr:'Matthieu situe ce discours sur une montagne, sans en préciser le nom (Matthieu 5, 1).',en:'Matthew places this teaching on a mountain without naming it (Matthew 5:1).'}},{q:{fr:'Qui est la première personne à voir Jésus ressuscité selon l’Évangile de Jean ?',en:'Who is the first person to see the risen Jesus in John’s Gospel?'},options:{fr:['Marie Madeleine','Pierre','Thomas'],en:['Mary Magdalene','Peter','Thomas']},correct:0,why:{fr:'Marie Madeleine rencontre Jésus ressuscité près du tombeau (Jean 20, 11-18).',en:'Mary Magdalene meets the risen Jesus near the tomb (John 20:11–18).'}}];
function readStore(key,fallback=[]){try{return JSON.parse(localStorage.getItem(key))??fallback}catch(_){return fallback}}
function dailyIndex(length){const n=new Date();return Math.floor((Date.UTC(n.getFullYear(),n.getMonth(),n.getDate())-Date.UTC(n.getFullYear(),0,1))/86400000)%length}
function renderInteractive(){const t=lang==='fr';document.querySelector('#tools-eyebrow').textContent=t?'POUR ALLER PLUS LOIN':'GO FURTHER';document.querySelector('#tools-heading').textContent=t?'Explorer et pratiquer':'Explore and practise';document.querySelector('#tools-subtitle').textContent=t?'Des outils pour lire, mémoriser et nourrir votre foi.':'Tools to read, remember, and nourish your faith.';document.querySelector('#bible-search-title').textContent=t?'Rechercher dans la Bible':'Search the Bible';document.querySelector('#bible-search-hint').textContent=t?'Cherchez un thème ou une référence dans les textes AELF.':'Search for a topic or passage in AELF texts.';document.querySelector('#bible-search-input').placeholder=t?'Ex. pardon, Jean 3…':'E.g. forgiveness, John 3…';document.querySelector('#bible-search-button').textContent=t?'Rechercher ↗':'Search ↗';document.querySelector('#reading-plan-title').textContent=t?'Parcours de lecture · 7 jours':'7-day reading plan';document.querySelector('#reading-plan-hint').textContent=t?'Une semaine pour découvrir la vie de Jésus.':'A week to discover the life of Jesus.';document.querySelector('#reading-plan-list').innerHTML=readingDays.map(([label,ref],i)=>`<li><a target="_blank" rel="noreferrer" href="${aelfLink(ref)}">${t?'Jour':'Day'} ${i+1} · ${label}</a></li>`).join('');document.querySelector('#daily-prayer-title').textContent=t?'Prière du jour':'Prayer of the day';document.querySelector('#daily-prayer-text').textContent=dailyPrayers[dailyIndex(dailyPrayers.length)][lang];document.querySelector('#new-prayer').textContent=t?'Afficher une autre prière':'Show another prayer';document.querySelector('#saint-title').textContent=t?'Repère du jour':'Faith note of the day';document.querySelector('#saint-text').textContent=dayFacts[dailyIndex(dayFacts.length)][lang];document.querySelector('#quiz-title').textContent=t?'Question biblique':'Bible quiz';document.querySelector('#favorites-title').textContent=t?'Mes favoris':'My favourites';document.querySelector('#favorites-hint').textContent=t?'Enregistrez une réponse depuis la conversation.':'Save a response from the conversation.';document.querySelector('#history-title').textContent=t?'Historique récent':'Recent history';document.querySelector('#clear-history').textContent=t?'Effacer l’historique':'Clear history';document.querySelector('#display-title').textContent=t?'Confort de lecture':'Reading comfort';document.querySelector('#font-label').textContent=t?'Taille du texte':'Text size';document.querySelector('#intent-title').textContent=t?'Mon intention de prière':'My prayer intention';document.querySelector('#intent-hint').textContent=t?'Enregistrée uniquement dans ce navigateur.':'Stored only in this browser.';document.querySelector('#prayer-intention').placeholder=t?'Écrivez votre intention (facultatif)…':'Write an intention (optional)…';document.querySelector('#save-intention').textContent=t?'Enregistrer sur cet appareil':'Save on this device';document.querySelector('#nav-assistant').textContent=t?'Assistant':'Assistant';document.querySelector('#nav-tools').textContent=t?'Explorer':'Explore';document.querySelector('#nav-resources').textContent=t?'Ressources':'Resources';renderQuiz();renderFavorites();renderHistory();const intent=localStorage.getItem('pc-intention')||'';document.querySelector('#prayer-intention').value=intent}
function renderQuiz(){const quiz=quizzes[dailyIndex(quizzes.length)],box=document.querySelector('#quiz-options');document.querySelector('#quiz-question').textContent=quiz.q[lang];document.querySelector('#quiz-result').textContent='';box.replaceChildren();quiz.options[lang].forEach((label,index)=>{const b=document.createElement('button');b.textContent=label;b.addEventListener('click',()=>{document.querySelector('#quiz-result').textContent=index===quiz.correct?quiz.why[lang]:(lang==='fr'?'Essaie encore. ':'Try again. ')+quiz.why[lang]});box.append(b)})}
function renderFavorites(){const box=document.querySelector('#favorites-list'),items=readStore('pc-favorites');box.replaceChildren();if(!items.length){box.textContent=lang==='fr'?'Aucun favori enregistré.':'No saved favourites yet.';return}items.slice().reverse().forEach((item,index)=>{const row=document.createElement('div');row.className='saved-item';row.textContent=item.slice(0,230);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label',lang==='fr'?'Supprimer':'Remove');remove.onclick=()=>{items.splice(items.length-1-index,1);localStorage.setItem('pc-favorites',JSON.stringify(items));renderFavorites()};row.append(remove);box.append(row)})}
function renderHistory(){const box=document.querySelector('#history-list'),items=readStore('pc-history');box.replaceChildren();items.slice(-5).reverse().forEach(item=>{const row=document.createElement('div');row.className='history-item';row.textContent=`${item.q} — ${item.a.slice(0,110)}…`;box.append(row)});if(!items.length)box.textContent=lang==='fr'?'Aucun échange récent.':'No recent conversations.'}
function renderSettings(){const t=lang==='fr';document.querySelector('#settings-eyebrow').textContent=t?'PERSONNALISER':'PERSONALIZE';document.querySelector('#settings-title').textContent=t?'Paramètres':'Settings';document.querySelector('#settings-reading-title').textContent=t?'Confort de lecture':'Reading comfort';document.querySelector('#settings-reading-hint').textContent=t?'Ajustez la taille du texte des réponses. Votre choix est mémorisé sur cet appareil.':'Adjust the assistant text size. Your choice is saved on this device.';document.querySelector('#font-label').textContent=t?'Taille du texte':'Text size';document.querySelector('#font-smaller').setAttribute('aria-label',t?'Réduire le texte':'Decrease text size');document.querySelector('#font-larger').setAttribute('aria-label',t?'Augmenter le texte':'Increase text size');document.querySelector('#settings-language').textContent=t?'Langue : Français':'Language: English';document.querySelector('#settings-theme').textContent=dark?(t?'Passer au mode clair':'Switch to light mode'):(t?'Passer au mode sombre':'Switch to dark mode');document.querySelector('#palette-title').textContent=t?'Couleur de fond':'Background colour';document.querySelector('#palette-hint').textContent=t?'Choisissez une teinte douce pour l’arrière-plan.':'Choose a soft background colour.';document.querySelectorAll('[data-palette]').forEach(b=>b.setAttribute('aria-pressed',document.body.dataset.palette===b.dataset.palette?'true':'false'));document.querySelector('#settings-open').setAttribute('aria-label',t?'Ouvrir les paramètres':'Open settings');document.querySelector('#settings-open').title=t?'Paramètres':'Settings'}
function updateReader(){const index=Number(document.querySelector('#reader-book').value)||0,book=bibleBooks[index],chapter=Number(document.querySelector('#reader-chapter').value)||1,url='https://www.aelf.org/bible/'+book[2]+'/'+chapter;document.querySelector('#bible-frame').src=url;const source=document.querySelector('#reader-open');source.href=url;source.textContent=lang==='fr'?'Ouvrir sur AELF ↗':'Open on AELF ↗';document.querySelector('#chapter-prev').disabled=index===0&&chapter===1;document.querySelector('#chapter-next').disabled=index===bibleBooks.length-1&&chapter===book[3];document.querySelector('#reader-frame-note').textContent=lang==='fr'?'Si le chapitre ne s’affiche pas dans le cadre, ouvre-le directement sur AELF.':'If the chapter does not appear here, open it directly on AELF.'}
function renderReader(){const fr=lang==='fr',bookSelect=document.querySelector('#reader-book'),index=Number(bookSelect.value)||0;document.querySelector('#bible-search-title').textContent=fr?'Lire la Bible':'Read the Bible';document.querySelector('#bible-search-hint').textContent=fr?'Choisis un livre et un chapitre à lire dans la Bible AELF.':'Choose a book and chapter to read in the AELF Bible.';document.querySelector('#book-label').textContent=fr?'Livre':'Book';document.querySelector('#chapter-label').textContent=fr?'Chapitre':'Chapter';document.querySelector('#reader-open').textContent=fr?'Ouvrir sur AELF ↗':'Open on AELF ↗';document.querySelector('#reader-frame-note').textContent=fr?'Si le chapitre ne s’affiche pas dans le cadre, ouvre-le directement sur AELF.':'If the chapter does not appear here, open it directly on AELF.';document.querySelector('#bible-search-input').placeholder=fr?'Rechercher un thème…':'Search a topic…';document.querySelector('#bible-search-button').textContent=fr?'Rechercher ↗':'Search ↗';document.querySelector('#reader-search-note').textContent=fr?'La recherche par thème ouvre les résultats du site AELF.':'Topic search opens results from the AELF website.';bookSelect.innerHTML=bibleBooks.map((book,i)=>'<option value="'+i+'">'+book[fr?0:1]+'</option>').join('');bookSelect.value=String(index);const book=bibleBooks[index],chapterSelect=document.querySelector('#reader-chapter'),old=Number(chapterSelect.value)||1;chapterSelect.innerHTML=Array.from({length:book[3]},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+'</option>').join('');chapterSelect.value=String(Math.min(old,book[3]));updateReader()}
function stepChapter(delta){let index=Number(document.querySelector('#reader-book').value)||0,chapter=Number(document.querySelector('#reader-chapter').value)||1;chapter+=delta;if(chapter<1&&index>0){index--;chapter=bibleBooks[index][3]}else if(chapter>bibleBooks[index][3]&&index<bibleBooks.length-1){index++;chapter=1}document.querySelector('#reader-book').value=String(index);renderReader();document.querySelector('#reader-chapter').value=String(chapter);updateReader()}
function initReader(){document.querySelector('#reader-book').addEventListener('change',()=>{document.querySelector('#reader-chapter').value='1';renderReader()});document.querySelector('#reader-chapter').addEventListener('change',updateReader);document.querySelector('#chapter-prev').addEventListener('click',()=>stepChapter(-1));document.querySelector('#chapter-next').addEventListener('click',()=>stepChapter(1));document.querySelector('#bible-frame').addEventListener('load',()=>{document.querySelector('#reader-frame-note').textContent=lang==='fr'?'Chapitre chargé depuis AELF. Si le cadre reste vide, ouvre-le avec le bouton ci-dessus.':'Chapter loaded from AELF. If the frame stays blank, use the button above.'})}
function showChurchMap(query){const encoded=encodeURIComponent(query),embed=document.querySelector('#churches-map'),external=document.querySelector('#churches-external');embed.src=`https://maps.google.com/maps?q=${encoded}&output=embed`;embed.hidden=false;external.href=`https://www.google.com/maps/search/?api=1&query=${encoded}`;external.hidden=false;document.querySelector('#churches-status').textContent=lang==='fr'?'Carte chargée. Les résultats et horaires sont fournis par Google Maps.':'Map loaded. Results and opening hours are provided by Google Maps.'}
function renderChurches(){const t=lang==='fr';document.querySelector('#churches-title').textContent=t?'Églises près de moi':'Churches near me';document.querySelector('#churches-hint').textContent=t?'Ta position n’est demandée qu’après ton clic. Google Maps reçoit la recherche.':'Your location is requested only after you click. Google Maps receives the search.';document.querySelector('#churches-locate').textContent=t?'Utiliser ma position':'Use my location';document.querySelector('#churches-place').placeholder=t?'Ville ou code postal':'City or postal code';document.querySelector('#churches-search').textContent=t?'Rechercher':'Search';document.querySelector('#churches-external').textContent=t?'Ouvrir dans Google Maps ↗':'Open in Google Maps ↗'}
function initChurches(){const nearby=t=>`${lang==='fr'?'églises près de':'churches near'} ${t}`;document.querySelector('#churches-locate').addEventListener('click',()=>{const status=document.querySelector('#churches-status');if(!navigator.geolocation){status.textContent=lang==='fr'?'La géolocalisation n’est pas disponible dans ce navigateur.':'Geolocation is not available in this browser.';return}status.textContent=lang==='fr'?'Demande de position…':'Requesting location…';navigator.geolocation.getCurrentPosition(pos=>showChurchMap(nearby(`${pos.coords.latitude},${pos.coords.longitude}`)),()=>{status.textContent=lang==='fr'?'Position refusée ou indisponible. Essaie avec une ville ou un code postal.':'Location denied or unavailable. Try a town or postal code.'},{enableHighAccuracy:false,timeout:10000,maximumAge:300000})});document.querySelector('#churches-search-form').addEventListener('submit',e=>{e.preventDefault();const place=document.querySelector('#churches-place').value.trim();if(place)showChurchMap(nearby(place))})}
function applyPalette(name){const allowed=['sage','rose','blue','yellow','lavender'];document.body.dataset.palette=allowed.includes(name)?name:'sage';localStorage.setItem('pc-palette',document.body.dataset.palette)}
function saveFavorite(text){const items=readStore('pc-favorites');if(!items.includes(text)){items.push(text);localStorage.setItem('pc-favorites',JSON.stringify(items));renderFavorites()}}
function initTools(){document.querySelector('#bible-search-form').addEventListener('submit',e=>{e.preventDefault();const q=document.querySelector('#bible-search-input').value.trim();if(!q)return;const url=`https://www.google.com/search?q=${encodeURIComponent('site:aelf.org/bible '+q)}`;window.open(url,'_blank','noopener,noreferrer')});document.querySelector('#new-prayer').addEventListener('click',()=>{const i=(dailyIndex(dailyPrayers.length)+1+Math.floor(Math.random()*(dailyPrayers.length-1)))%dailyPrayers.length;document.querySelector('#daily-prayer-text').textContent=dailyPrayers[i][lang]});document.querySelector('#save-intention').addEventListener('click',()=>{localStorage.setItem('pc-intention',document.querySelector('#prayer-intention').value.trim());document.querySelector('#intent-status').textContent=lang==='fr'?'Enregistrée sur cet appareil.':'Saved on this device.'});document.querySelector('#clear-history').addEventListener('click',()=>{localStorage.removeItem('pc-history');renderHistory()});let size=Number(localStorage.getItem('pc-font-size'))||14;const applySize=()=>{document.documentElement.style.setProperty('--reading-size',size+'px');document.querySelectorAll('.bubble').forEach(x=>x.style.fontSize=size+'px')};applySize();document.querySelector('#font-smaller').addEventListener('click',()=>{size=Math.max(12,size-1);localStorage.setItem('pc-font-size',size);applySize()});document.querySelector('#font-larger').addEventListener('click',()=>{size=Math.min(20,size+1);localStorage.setItem('pc-font-size',size);applySize()});document.querySelector('#daily-verse').addEventListener('click',()=>saveFavorite(document.querySelector('#daily-verse').textContent+' '+document.querySelector('#daily-ref').textContent));document.querySelector('#daily-verse').title=lang==='fr'?'Cliquer pour enregistrer dans les favoris':'Click to save to favourites';document.querySelector('#daily-verse').style.cursor='pointer';conversation.addEventListener('click',async e=>{const action=e.target.closest('[data-action]');if(!action)return;const msg=action.closest('.message'),bubble=msg?.querySelector('.bubble');if(!bubble)return;const content=bubble.innerText;if(action.dataset.action==='save'){saveFavorite(content);action.textContent=lang==='fr'?'Enregistré ✓':'Saved ✓'}if(action.dataset.action==='copy'){try{await navigator.clipboard.writeText(content);action.textContent=lang==='fr'?'Copié ✓':'Copied ✓'}catch(_){action.textContent=lang==='fr'?'Copie indisponible':'Copy unavailable'}}if(action.dataset.action==='share'){if(navigator.share){try{await navigator.share({title:'IA Bible',text:content})}catch(_){}}else{try{await navigator.clipboard.writeText(content);action.textContent=lang==='fr'?'Copié pour partager ✓':'Copied to share ✓'}catch(_){}}}const q=action.dataset.q;if(q)submit(lang==='fr'?q:action.dataset.qEn)});document.querySelectorAll('.mobile-nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.mobile-nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active')}))}
function searchPraiseVideos(){const query=document.querySelector('#praise-search').value.trim();if(!query)return;const box=document.querySelector('#youtube-results');box.replaceChildren();const status=document.createElement('p');status.className='youtube-hint';status.textContent=messages[lang].youtubeLoading;box.append(status);const searchUrl=`https://www.youtube.com/results?search_query=${encodeURIComponent(query+' louange chrétienne')}`;(async()=>{try{const response=await fetch(`/api/praise-search?q=${encodeURIComponent(query)}`);if(!response.ok)throw new Error('API unavailable');const data=await response.json();box.replaceChildren();if(!data.configured){const note=document.createElement('p');note.className='youtube-hint';note.textContent=messages[lang].youtubeApiHint;box.append(note);const link=document.createElement('a');link.className='youtube-fallback';link.href=data.youtubeSearchUrl||searchUrl;link.target='_blank';link.rel='noreferrer';link.textContent=lang==='fr'?'Voir les résultats sur YouTube ↗':'Open YouTube results ↗';box.append(link);return}if(!data.items?.length){const note=document.createElement('p');note.className='youtube-hint';note.textContent=messages[lang].youtubeNoResults;box.append(note);return}for(const item of data.items){const card=document.createElement('a');card.className='youtube-result';card.href=`https://www.youtube.com/watch?v=${encodeURIComponent(item.id)}`;card.target='_blank';card.rel='noreferrer';const img=document.createElement('img');img.src=item.thumbnail;img.alt='';img.loading='lazy';const info=document.createElement('span'),title=document.createElement('b'),channel=document.createElement('small');title.textContent=item.title;channel.textContent=item.channel;info.append(title,channel);card.append(img,info);box.append(card)}}catch(_){box.replaceChildren();const link=document.createElement('a');link.className='youtube-fallback';link.href=searchUrl;link.target='_blank';link.rel='noreferrer';link.textContent=lang==='fr'?'Rechercher sur YouTube ↗':'Search YouTube ↗';box.append(link)}})()}
document.querySelector('#praise-search').addEventListener('input',renderPraises);document.querySelector('#youtube-search').addEventListener('click',searchPraiseVideos);document.querySelector('#praise-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchPraiseVideos()}});renderResources();initTools();initReplyActions();form.addEventListener('submit',()=>setReplyButtons(false));conversation.addEventListener('click',e=>{if(e.target.closest('[data-q]'))setReplyButtons(false)});initReader();applyPalette(localStorage.getItem('pc-palette'));renderInteractive();renderReader();renderSettings();initChurches();renderChurches();document.querySelectorAll('[data-palette]').forEach(b=>b.addEventListener('click',()=>{applyPalette(b.dataset.palette);renderSettings()}));document.querySelector('#language').addEventListener('click',()=>{renderReader();renderChurches();renderSettings()});
const settingsDialog=document.querySelector('#settings-dialog');document.querySelector('#settings-open').addEventListener('click',()=>{renderSettings();settingsDialog.showModal()});document.querySelector('#settings-language').addEventListener('click',()=>{document.querySelector('#language').click();renderSettings()});document.querySelector('#settings-theme').addEventListener('click',()=>{document.querySelector('#theme').click();renderSettings()});





